const money = (minor, currency) => Object.freeze({
  minor, currency,
  add(other) {
    if (this.currency !== other.currency) throw new Error("currency mismatch");
    return money(this.minor + other.minor, this.currency);
  },
  scale(factor) { return money(this.minor * factor, this.currency); },
});

const total = lines.map(l => l.price).reduce((a, b) => a.add(b), money(0, "EUR"));
